// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address candidateNewOwner) public {
        vm.assume(caller != address(0));
        vm.assume(candidateNewOwner != address(0));

        address deployer = address(this);
        vm.assume(caller != deployer);

        c.setOwner(caller);

        bool ok;
        vm.prank(caller);
        try c.setOwner(candidateNewOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.owner() == caller);
    }
}
